'use client';
import React from 'react';

interface StreakHeatmapProps {
  riwayat: { rawDate?: string; tanggal: string }[];
  isDarkMode: boolean;
}

export default function StreakHeatmap({ riwayat, isDarkMode }: StreakHeatmapProps) {
  // Mengambil daftar tanggal unik dari riwayat catatan
  const setTanggalAktif = new Set(riwayat.map(item => item.rawDate || item.tanggal));

  // Menghasilkan 14 hari terakhir untuk ditampilkan sebagai visualisasi mini
  const generateHariTerakhir = () => {
    const listHari = [];
    for (let i = 13; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const rawString = d.toISOString().split('T')[0];
      const formattedString = d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
      
      const adaCatatan = setTanggalAktif.has(rawString) || setTanggalAktif.has(formattedString);
      listHari.push({
        tanggalStr: formattedString,
        adaCatatan,
      });
    }
    return listHari;
  };

  const dataHari = generateHariTerakhir();

  return (
    <div className={`p-4 rounded-2xl border space-y-2.5 ${
      isDarkMode ? 'bg-black/20 border-[#7A8A76]/15' : 'bg-white/60 border-[#8A9A86]/15'
    }`}>
      <div className="flex justify-between items-center">
        <span className={`text-[10px] font-semibold uppercase tracking-wider block ${isDarkMode ? 'text-[#A2B59F]' : 'text-[#6E7D6A]'}`}>
          🔥 Jejak 2 Minggu Terakhir
        </span>
        <span className="text-[10px] opacity-50 font-mono">Konsistensi Harian</span>
      </div>

      <div className="flex justify-between items-center gap-1 pt-1">
        {dataHari.map((hari, idx) => (
          <div
            key={idx}
            title={`${hari.tanggalStr}: ${hari.adaCatatan ? 'Ada catatan refleksi' : 'Belum ada catatan'}`}
            className={`h-7 flex-1 rounded-md transition-all ${
              hari.adaCatatan 
                ? 'bg-[#7A8A76] shadow-2xs' 
                : isDarkMode ? 'bg-white/5 border border-white/5' : 'bg-[#8A9A86]/10'
            }`}
          />
        ))}
      </div>
    </div>
  );
}